import ast, importlib.util, pathlib, subprocess, sys, tempfile
from unittest.mock import patch
root=pathlib.Path('/private/tmp/claude-ticket-dispatch-20261030')
spec=importlib.util.spec_from_file_location('task_actions',root/'hooks/lib/task_actions.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
count=0
def check(name, fn):
 global count
 fn();count+=1;print('PASS',name)
def no_python(error):
 with patch.object(m.ast,'parse',side_effect=error): assert not m._python_read(['python3','-I','-c','print(1)'])
for e in (ValueError('parse failed'),SyntaxError('bad syntax')): check('python invalid parse '+type(e).__name__,lambda e=e:no_python(e))
for e in (subprocess.SubprocessError('git failed'),OSError('unavailable')):
 def git_bad(e=e):
  with patch.object(m.subprocess,'check_output',side_effect=e):
   try:m._git_toplevel(str(root))
   except m.UnknownShape: return
   raise AssertionError('Git error permitted')
 check('git toplevel '+type(e).__name__,git_bad)
class BadReads:
 def main(self,_):raise RuntimeError('classifier unavailable')
def released_bad():
 with patch.object(m,'_RELEASED_READS',BadReads()): assert m.released_read_verdict('git status')==1
check('released reader failure is unproven',released_bad)
def producer_bad():
 tokens=m.shell_tokens('python3 '+str(root/'hooks/lib/test-evidence.py')+' record')
 with patch.object(m.os,'stat',side_effect=OSError('producer unavailable')):
  try:m._test_receipt_record(tokens,str(root))
  except m.UnknownShape:return
  raise AssertionError('producer stat permitted')
check('missing producer no execution lane',producer_bad)
for e in (OSError('unreadable'),ValueError('invalid path')):
 def body_bad(e=e):
  with patch.object(m.os,'open',side_effect=e):
   try:m._metadata_file('body.md',str(root))
   except m.UnknownShape:return
   raise AssertionError('metadata failure permitted')
 check('metadata input '+type(e).__name__,body_bad)
def initial_bad():
 with patch.object(m,'_test_receipt_record',side_effect=m.UnknownShape('invalid producer')):
  result=m._action('true',str(root));assert result.get('error') and not result['read_only'] and result['paths']==[str(root)]
check('initial unknown shape retains mutation target',initial_bad)
def segment_bad():
 with patch.object(m,'github_metadata_target',side_effect=m.UnknownShape('unreadable metadata')):
  result=m._action('gh pr edit 123 --body text',str(root));assert result.get('error') and not result['read_only'] and str(root) in result['paths'] and not result.get('metadata_only')
check('segment unknown shape retains mutation target',segment_bad)
base=ast.parse(subprocess.check_output(['git','show','b3c560b:hooks/lib/task_actions.py'],cwd=root,text=True))
now=ast.parse((root/'hooks/lib/task_actions.py').read_text())
old={n.name:n for n in base.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
for n in now.body:
 if isinstance(n,ast.FunctionDef) and n.name in {'_python_read','_git_toplevel','released_read_verdict','_test_receipt_record','_metadata_file','_action'}:
  assert ast.dump(n,include_attributes=False)==ast.dump(old[n.name],include_attributes=False),n.name
  print('AST_UNCHANGED',n.name)
print('PASS controls',count)
